package local.lito381.server;
import java.io.IOException;import java.util.*;
/** Accepted proc healing output; queued records retain no Frame, Context, snapshot, or audience map. */
final class NativeSourceEquipmentOutput {
 private static final java.lang.invoke.VarHandle SLOT=slot();
 static java.lang.invoke.VarHandle slot(){try{return java.lang.invoke.MethodHandles.lookup().findVarHandle(NativePlayerCommit.Frame.class,"nativeSourceEquipmentOutputScope",Object.class);}catch(ReflectiveOperationException failure){throw new ExceptionInInitializerError(failure);}}
 record Link(Scope scope,Object previous){}
 record Detached(NativeSourceAcceptedPlayers.Participant caster,NativeSourceAcceptedPlayers.Participant target,NativePlayerLifetime lifetime,GameHub hub,int hp,int maximum,boolean committed){
  boolean targetCurrent(){return target!=null&&lifetime!=null&&hub!=null&&lifetime.mode!=NativePlayerLifetime.Mode.STOPPED&&!(boolean)CombatAccess.field(hub,"nativeStaticMotionClosed")&&NativeSourceEquipmentProcLife.participant(target,hub)&&!(boolean)CombatAccess.field(target.pc(),"observer");}
  boolean casterCurrent(){return caster!=null&&NativeSourceEquipmentProcLife.participant(caster,hub)&&!(boolean)CombatAccess.field(caster.pc(),"observer");}
 }
 record Viewer(ClientSession pc,NativePlayerCommit.Binding binding,Object life,boolean observer){boolean current(GameHub hub){return binding!=null&&NativeAcceptedFreezeMutation.roleFrame(binding,pc)&&!(boolean)CombatAccess.field(pc,"sourceItemDisconnected")&&CombatAccess.field(pc,"hub")==hub&&(observer?(boolean)CombatAccess.field(pc,"observer"):life!=null&&NativeSourceControlledDisplay.rawLife(pc)==life);}}
 static final class Scope {final long thread=Thread.currentThread().getId();volatile boolean closed;final Detached proof;final int skill,gfx;final IdentityHashMap<ClientSession,Viewer> viewers=new IdentityHashMap<>();Scope(Detached proof,int skill,int gfx){this.proof=proof;this.skill=skill;this.gfx=gfx;for(var p:List.of(proof.caster(),proof.target()))viewers.putIfAbsent(p.pc(),new Viewer(p.pc(),p.binding(),p.life(),false));}}
 record Output(Detached proof,Viewer viewer,int gfx,int kind,byte[] packet,String note){Output{packet=packet.clone();}}
 static Object born(Object target){var f=NativePlayerCommit.frame();if(f==null||!NativeSourceEquipmentProcLife.enabled(f.pc))return null;return born(NativeSourceEquipmentProcLife.proof(f.pc,(ClientSession)CombatAccess.field(target,"pc")),target);}
 static Detached born(NativeSourceEquipmentProcLife.Proof proof,Object target){return proof==null||!proof.current()||proof.target().pc()!=(ClientSession)CombatAccess.field(target,"pc")?new Detached(null,null,null,null,0,0,false):new Detached(proof.caster(),proof.target(),proof.lifetime(),proof.hub(),NativeSourceRawDamage.number(target,"before"),NativeSourceRawDamage.number(target,"maximum"),false);}
 static void seal(Object target){if(CombatAccess.field(target,"nativeSourceEquipmentOutputProof") instanceof Detached d&&!d.committed()&&d.targetCurrent()&&d.target().pc()==(ClientSession)CombatAccess.field(target,"pc"))CombatAccess.set(target,"nativeSourceEquipmentOutputProof",new Detached(d.caster(),d.target(),d.lifetime(),d.hub(),NativeSourceRawDamage.number(target,"after"),NativeSourceRawDamage.number(target,"maximum"),true));}
 static Scope scope(){var f=NativePlayerCommit.frame();if(f==null)return null;Object head=SLOT.getVolatile(f);long thread=Thread.currentThread().getId();while(head instanceof Link link){if(link.scope().thread==thread&&!link.scope().closed)return link.scope();head=link.previous();}return null;}
 static void push(NativePlayerCommit.Frame frame,Scope scope){Object old;do{old=SLOT.getVolatile(frame);}while(!SLOT.compareAndSet(frame,old,new Link(scope,old)));}
 static void pop(NativePlayerCommit.Frame frame,Scope scope){for(;;){Object head=SLOT.getVolatile(frame),cursor=head;var retained=new ArrayList<Scope>();while(cursor instanceof Link link){if(link.scope()!=scope&&!link.scope().closed)retained.add(link.scope());cursor=link.previous();}Object replacement=cursor;for(int i=retained.size()-1;i>=0;i--)replacement=new Link(retained.get(i),replacement);if(SLOT.compareAndSet(frame,head,replacement))return;}}

 static boolean scoped(Object snapshot,int skill,int gfx,Runnable original){var f=NativePlayerCommit.frame();if(f==null||!(CombatAccess.field(snapshot,"nativeSourceEquipmentOutputProof") instanceof Detached d)||!d.targetCurrent())return false;var s=new Scope(d,skill,gfx);push(f,s);try{original.run();return true;}finally{s.closed=true;try{pop(f,s);}finally{s.viewers.clear();}}}

 static void complete(ClientSession caster,NativePlayerCommit.Binding source,ClientSession target,NativePlayerCommit.Binding binding,int skill,int gfx,Object snapshot){var t=snapshot;if(!(CombatAccess.field(t,"nativeSourceEquipmentOutputProof") instanceof Detached)){NativeProcHealingPlayer.nativeSourceEquipmentOutputOriginalComplete(caster,source,target,binding,skill,gfx,snapshot);return;}scoped(t,skill,gfx,()->NativeProcHealingPlayer.nativeSourceEquipmentOutputOriginalComplete(caster,source,target,binding,skill,gfx,snapshot));}
 static boolean completeFrame(ClientSession caster,ClientSession target){var s=scope();return s==null?NativeSourceEquipmentProcLife.validFrame(caster,target):s.proof.caster()!=null&&s.proof.caster().pc()==caster&&s.proof.target().pc()==target&&s.proof.targetCurrent();}
 static boolean graphicsFrame(ClientSession caster,ClientSession target){var s=scope();return s==null?NativeSourceEquipmentProcLife.validFrame(caster,target):completeFrame(caster,target)&&s.proof.casterCurrent();}
 static List<ClientSession> members(GameHub hub,long room){var s=scope();if(s==null)return hub.roomMembers(room);synchronized(hub){var list=hub.roomMembers(room);remember(s,hub,room,list);return list;}}
 static void remember(Scope s,GameHub hub,long room,List<ClientSession> list){if(!Thread.holdsLock(hub))throw new IllegalStateException("proc audience requires original Hub discovery ownership");if(s.proof.hub()!=hub||s.proof.target().binding().room()!=room)return;for(var pc:list)if(!s.viewers.containsKey(pc)){var first=NativeSourceEquipmentFinalOutput.first(pc);Object life=NativeSourceControlledDisplay.rawLife(pc);var binding=NativePlayerCommit.Binding.capture(pc);s.viewers.put(pc,NativeSourceEquipmentFinalOutput.viewer(pc,binding,life,(boolean)CombatAccess.field(pc,"observer"),first));}}
 static int kind(byte[] packet){if(packet==null||packet.length==0)return -1;return switch(packet[0]&255){case 13->0;case 104->1;case 55->2;default->-1;};}
 static byte[] expected(Detached d,int gfx,int kind){return switch(kind){case 0->new Protocol.Writer().c(Protocol.S_HIT_POINT).h(d.hp()).h(d.maximum()).bytes();case 1->Protocol.hitRatio(d.target().binding().object(),d.hp(),d.maximum());case 2->Protocol.effectObject(d.target().binding().object(),gfx);default->new byte[0];};}
 static Output output(Scope s,ClientSession receiver,byte[] packet,String note){int kind=kind(packet);var viewer=s.viewers.get(receiver);if(kind<0||viewer==null||kind==0&&receiver!=s.proof.target().pc())return null;var d=s.proof;var proof=kind==2?d:new Detached(null,d.target(),d.lifetime(),d.hub(),d.hp(),d.maximum(),d.committed());var out=new Output(proof,viewer,s.gfx,kind,packet,note);return current(out)?out:null;}
 static boolean current(Output out){if(out==null||out.kind()<0||out.kind()>2||!out.proof().targetCurrent()||!out.viewer().current(out.proof().hub())||!Arrays.equals(out.packet(),expected(out.proof(),out.gfx(),out.kind())))return false;var d=out.proof();if(out.kind()!=2)return d.committed()&&NativeSourceRawDamage.number(d.target().pc(),"playerHp")==d.hp()&&NativeSourceRawDamage.number(d.target().pc(),"playerMaxHp")==d.maximum()&&(out.kind()==0?out.viewer().pc()==d.target().pc():NativeSourceOtherControls.settings().hpbar());if(out.gfx()<=0||!d.casterCurrent()||!d.caster().pc().nativeSourceShowProcSpr)return false;return Math.max(Math.abs((long)NativeSourceRawDamage.number(out.viewer().pc(),"positionX")-NativeSourceRawDamage.number(d.caster().pc(),"positionX")),Math.abs((long)NativeSourceRawDamage.number(out.viewer().pc(),"positionY")-NativeSourceRawDamage.number(d.caster().pc(),"positionY")))<=10;}
 static boolean capture(ClientSession receiver,byte[] packet,String note){var s=scope();if(s==null||kind(packet)<0)return false;var out=output(s,receiver,packet,note);if(out!=null)NativeLightAction.deferScoped(()->send(out));return true;}
 static void hp(ClientSession receiver,byte[] packet,String note){if(!capture(receiver,packet,note))NativePlayerCommit.safeAuxSend(receiver,packet,note);}
 static void send(Output out){if(!current(out))return;NativePlayerCommit.completionFrame(null,()->{var old=NativeAreaMaterialAction.current.get();NativeAreaMaterialAction.current.remove();try{if(!current(out))return;var c=new NativeAreaMaterialAction.Context(out.viewer().pc());c.nativeSourceCubeStatusProof=out;try{NativeAreaMaterialAction.owned(c,()->{synchronized(out.viewer().pc()){if(current(out))out.viewer().pc().nativeSelfOriginalSend(out.packet(),out.note());}});}finally{c.nativeSourceCubeStatusProof=null;}}catch(IOException|RuntimeException failure){NativeSourcePhysicalNpc.failed(out.proof().lifetime());}finally{if(old==null)NativeAreaMaterialAction.current.remove();else NativeAreaMaterialAction.current.set(old);}});}
 static boolean allowFrame(ClientSession pc,byte[] packet){var c=NativeAreaMaterialAction.current.get();return c==null||!(c.nativeSourceCubeStatusProof instanceof Output out)||out.viewer().pc()==pc&&Arrays.equals(out.packet(),packet)&&current(out);}
 private NativeSourceEquipmentOutput(){}
}
